questionvariables.text:
/* Helper: position (1-3) of the correct option (value 1) within a shuffled dropdown list */
correctpos(ta) := first(sublist_indices(map(first, ta), lambda([v], is(v = 1))));
/* A wrong option's value, for question testing */
wrongval(ta)   := first(delete(1, map(first, ta)));

/* --- 1. DATA (Input 1) --- */
correct_text_da: "A collection of facts, figures, numbers, observations, or measurements that can be recorded and used to study something.";
wrongs_da: [
    "The final conclusions and recommendations drawn after a study is complete.",
    "A graph or chart used to display information visually.",
    "The average value calculated from a set of numbers.",
    "A small group of people selected to represent a population.",
    "The software tools used to analyse numerical information."
];
correct_ans_da: rand_selection([[1, true, correct_text_da]], 1);
wrong_ans_da: rand_selection([
    [2, false, wrongs_da[1]],
    [3, false, wrongs_da[2]],
    [4, false, wrongs_da[3]],
    [5, false, wrongs_da[4]],
    [6, false, wrongs_da[5]]
], 3);
ta_da: random_permutation(append(correct_ans_da, wrong_ans_da));

/* --- 2. PRIMARY DATA (Input 2) --- */
correct_text_pd: "Data collected first-hand by the researcher for the specific study at hand.";
wrongs_pd: [
    "Information obtained from existing records such as government censuses or textbooks.",
    "Data that has already been published and analysed by another author.",
    "A summary of research compiled from many other studies.",
    "News articles reporting on a past event.",
    "Figures copied from a published statistical report."
];
correct_ans_pd: rand_selection([[1, true, correct_text_pd]], 1);
wrong_ans_pd: rand_selection([
    [2, false, wrongs_pd[1]],
    [3, false, wrongs_pd[2]],
    [4, false, wrongs_pd[3]],
    [5, false, wrongs_pd[4]],
    [6, false, wrongs_pd[5]]
], 3);
ta_pd: random_permutation(append(correct_ans_pd, wrong_ans_pd));

/* --- 3. SECONDARY DATA (Input 3) --- */
correct_text_sd: "Data already collected by someone else for a different purpose, which the researcher now re-uses.";
wrongs_sd: [
    "Information a researcher collects first-hand through their own surveys or experiments.",
    "Measurements you record yourself during a science experiment.",
    "Responses gathered directly from interviewing participants.",
    "Original observations made by the investigator for this specific study.",
    "First-hand counts taken by a student during fieldwork."
];
correct_ans_sd: rand_selection([[1, true, correct_text_sd]], 1);
wrong_ans_sd: rand_selection([
    [2, false, wrongs_sd[1]],
    [3, false, wrongs_sd[2]],
    [4, false, wrongs_sd[3]],
    [5, false, wrongs_sd[4]],
    [6, false, wrongs_sd[5]]
], 3);
ta_sd: random_permutation(append(correct_ans_sd, wrong_ans_sd));

/* Short summary of this variant for the question note */
variantnote: sconcat("correct positions a/b/c = ",
    correctpos(ta_da), "/", correctpos(ta_pd), "/", correctpos(ta_sd));
